properties.$st-css:
:import{
    -st-from: 'wix-ui-santa/index.st.css';
    -st-named: StylableButton
}
.root{
    -st-extends: StylableButton;
    transition: all 0.2s ease, visibility 0s;
    border: 3px solid #BDCBAE;
    background: rgba(255, 255, 255, 0.94)
}
.root:hover{
    background: #0038FF;
    border: 1px solid #0038FF
}
.root:hover::label{
    color: #FFFFFF
}
.root:disabled{
    background: #E2E2E2
}
.root:disabled::label{
    color: #8F8F8F
}
.root:disabled::icon{
    fill: #8F8F8F
}
.root::container{
    transition: inherit
}
.root::label{
    transition: inherit;
    font-family: futura-lt-w01-book,sans-serif;
    margin: 0px 4px 0px 0px;
    font-size: 14px;
    color: #000000;
    letter-spacing: 0em;
    -st-mixin: font_8;
    font-weight: 400
}
.root::icon{
    transition: inherit;
    width: 10px;
    height: 10px;
    margin: 0px 0px 0px 4px;
    fill: #FFFFFF;
    display: none
}
.root:hover::icon{
    fill: #000000
}
@media value(mobileMediaQuery) {
    .root::label {
        -st-mixin: font_8;
        font-size: 10px;
        font-weight: 400;
    }
}
